// 06 - Cross-core sync: semaphore ping-pong, queue, event flags, barrier.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "smp_helpers.hpp"

using namespace os::rtos;
using namespace mtp_smp;

namespace
{
  constexpr unsigned rounds = 1000;
  semaphore_binary* g_ping = nullptr;
  semaphore_binary* g_pong = nullptr;
  volatile unsigned g_pongs = 0;
  volatile unsigned g_ponger_core = 0xff;

  void*
  ponger (void*)
  {
    store (g_ponger_core, mtp_board::cpu_id ());
    for (unsigned i = 0; i < rounds; ++i)
      {
        (void)g_ping->wait ();
        g_pongs = g_pongs + 1;
        (void)g_pong->post ();
      }
    return nullptr;
  }

  constexpr unsigned messages = 1000;
  message_queue_typed<std::uint64_t>* g_queue = nullptr;
  volatile unsigned g_producer_core = 0xff;

  void*
  producer (void*)
  {
    store (g_producer_core, mtp_board::cpu_id ());
    for (std::uint64_t value = 1; value <= messages; ++value)
      {
        (void)g_queue->send (&value);
      }
    return nullptr;
  }

  event_flags* g_flags = nullptr;

  void*
  raise_own_flag (void* arg)
  {
    const unsigned core = from_arg (arg);
    sysclock.sleep_for (ms (5 + core * 3));
    if (mtp_board::cpu_id () == core)
      {
        (void)g_flags->raise (1u << core);
      }
    return nullptr;
  }

  // A sense-reversing barrier over the spinlock: every core, many rounds.
  constexpr unsigned barrier_rounds = 200;
  mtp_board::spinlock* g_barrier_lock = nullptr;
  volatile unsigned g_arrived = 0;
  volatile unsigned g_generation = 0;
  volatile unsigned g_barrier_timeouts = 0;
  volatile unsigned g_barrier_rounds_done[ncpu];

  void*
  barrier_worker (void* arg)
  {
    const unsigned core = from_arg (arg);
    for (unsigned r = 0; r < barrier_rounds; ++r)
      {
        const unsigned generation = load (g_generation);
        g_barrier_lock->lock ();
        const unsigned arrived = g_arrived + 1;
        if (arrived == ncpu)
          {
            g_arrived = 0;
            g_barrier_lock->unlock ();
            store (g_generation, generation + 1);
          }
        else
          {
            g_arrived = arrived;
            g_barrier_lock->unlock ();
            const auto begin = sysclock.now ();
            while (load (g_generation) == generation)
              {
                if (sysclock.now () - begin > ms (1000))
                  {
                    store (g_barrier_timeouts, load (g_barrier_timeouts) + 1);
                    return nullptr;
                  }
                mtp_board::cpu_relax ();
              }
          }
        store (g_barrier_rounds_done[core], r + 1);
      }
    return nullptr;
  }
} // namespace

mt::static_suite suite_cross_core{
  "06 - Cross-core sync", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("semaphore ping-pong between core 0 and core 1", [] (auto& t) {
      semaphore_binary ping{ "mtp-ping", 0 };
      semaphore_binary pong{ "mtp-pong", 0 };
      g_ping = &ping;
      g_pong = &pong;
      g_pongs = 0;
      thread* th = spawn ("mtp-ponger", ponger, nullptr, 1);
      unsigned answered = 0;
      for (unsigned i = 0; i < rounds; ++i)
        {
          (void)ping.post ();
          if (pong.timed_wait (ms (100)) == result::ok)
            {
              ++answered;
            }
        }
      finish (th);
      t.expect (mt::eq (answered, rounds)) << "1000 round trips";
      t.expect (mt::eq (static_cast<unsigned> (g_pongs), rounds)) << "1000 answers";
      t.expect (mt::eq (load (g_ponger_core), 1u)) << "the ponger on core 1";
    });

    ts.test ("a message queue from the last core to core 0 keeps order",
             [] (auto& t) {
               message_queue_typed<std::uint64_t> queue{ "mtp-xq", 16 };
               g_queue = &queue;
               thread* th = spawn ("mtp-producer", producer, nullptr,
                                   static_cast<int> (last));
               std::uint64_t expected = 1;
               std::uint64_t sum = 0;
               bool ordered = true;
               for (unsigned i = 0; i < messages; ++i)
                 {
                   std::uint64_t value = 0;
                   if (queue.timed_receive (&value, ms (1000)) != result::ok)
                     {
                       break;
                     }
                   ordered = ordered && value == expected;
                   ++expected;
                   sum += value;
                 }
               finish (th);
               t.expect (mt::eq (sum, std::uint64_t{ 500500 }))
                   << "1..1000 all received";
               t.expect (ordered) << "in order";
               t.expect (mt::eq (load (g_producer_core), last))
                   << fmt ("sent from core %u", last);
             });

    ts.test ("each core raises its flag, core 0 waits for all", [] (auto& t) {
      event_flags ev{ "mtp-flags" };
      g_flags = &ev;
      thread* threads[ncpu] = {};
      for (unsigned core = 0; core < ncpu; ++core)
        {
          threads[core] = spawn ("mtp-raise", raise_own_flag, as_arg (core),
                                 static_cast<int> (core));
        }
      const flags::mask_t all = (1u << ncpu) - 1u;
      flags::mask_t got = 0;
      const auto waited = ev.timed_wait (all, ms (1000), &got);
      for (auto* th : threads)
        {
          finish (th);
        }
      t.expect (mt::eq (waited, mtp::ok)) << "all within 1 s";
      t.expect (mt::eq (got, all)) << "one flag per core";
    });

    ts.test ("every core meets at a barrier, round after round", [] (auto& t) {
      mtp_board::spinlock lock;
      g_barrier_lock = &lock;
      g_arrived = 0;
      store (g_generation, 0u);
      store (g_barrier_timeouts, 0u);
      thread* threads[ncpu] = {};
      for (unsigned core = 0; core < ncpu; ++core)
        {
          store (g_barrier_rounds_done[core], 0u);
          threads[core] = spawn ("mtp-barrier", barrier_worker, as_arg (core),
                                 static_cast<int> (core));
        }
      for (auto* th : threads)
        {
          finish (th);
        }
      t.expect (mt::eq (load (g_barrier_timeouts), 0u)) << "no core timed out";
      t.expect (mt::eq (load (g_generation), barrier_rounds))
          << fmt ("%u generations", barrier_rounds);
      for (unsigned core = 0; core < ncpu; ++core)
        {
          t.expect (mt::eq (load (g_barrier_rounds_done[core]), barrier_rounds))
              << fmt ("core %u passed every round", core);
        }
    });
  }
};
